export function onModules(mods     )       {
    modFull = mods[0];
    modLite = mods[1];
    modTerm = mods[2];
    scanX = exportsOf(instantiate(modLite));
    scanU8 = u8Of(scanX);
    scanX.nk_scan_reset();
    named = {};
    toolLabels = {};
    ptrs = {};
    pins = storeJson("pins", []);
    wireUiBang();
    renderSavedBang();
    renderDevicesBang();
    showViewBang("devices");
    ready = true;
    statusBang(netLabel(pickCidr(localInfo())));
    win().requestAnimationFrame(termFrame);
    win().requestAnimationFrame(vncFrame);
    setInterval(blinkBang, 530);
    if (haveNativeP()) {
        startScanBang();
    }
}

export function boot()       {
    nat = ((typeof NetkitNative !== "undefined") ? NetkitNative : null);
    win().netkitEvent = onNative;
    win().netkitBack = nkBack;
    Promise.all([fetchModule("netkit.wasm"), fetchModule("netkit-lite.wasm"), fetchModule("nkterm.wasm")]).then(onModules).catch(failBootBang);
}

boot();
